'use strict'

const MODEL_SIZE = 64
const CHANNEL_SIZE = MODEL_SIZE * MODEL_SIZE
const DEFAULT_GUIDE_RECT = Object.freeze({
  x: 0.16,
  y: 0.16,
  width: 0.68,
  height: 0.62,
})

function assertYawSign(value) {
  if (value !== 1 && value !== -1) {
    throw new Error('yawSign 必须是 1 或 -1')
  }
  return value
}

function normalizeGuideRect(rect) {
  const result = Object.assign({}, DEFAULT_GUIDE_RECT, rect || {})
  const values = [result.x, result.y, result.width, result.height]
  if (!values.every(Number.isFinite)) {
    throw new Error('guideRect 必须全部是有限数字')
  }
  if (result.x < 0 || result.y < 0 || result.width <= 0 || result.height <= 0) {
    throw new Error('guideRect 超出有效范围')
  }
  if (result.x + result.width > 1 || result.y + result.height > 1) {
    throw new Error('guideRect 必须位于画面内部')
  }
  return result
}

function asUint8Array(data) {
  if (data instanceof ArrayBuffer) return new Uint8Array(data)
  if (ArrayBuffer.isView(data)) {
    return new Uint8Array(data.buffer, data.byteOffset, data.byteLength)
  }
  throw new Error('相机帧 data 必须是 ArrayBuffer 或 TypedArray')
}

function sampleRgbaBilinear(bytes, frameWidth, frameHeight, x, y, channel) {
  const clampedX = Math.max(0, Math.min(frameWidth - 1, x))
  const clampedY = Math.max(0, Math.min(frameHeight - 1, y))
  const x0 = Math.floor(clampedX)
  const y0 = Math.floor(clampedY)
  const x1 = Math.min(frameWidth - 1, x0 + 1)
  const y1 = Math.min(frameHeight - 1, y0 + 1)
  const dx = clampedX - x0
  const dy = clampedY - y0
  const p00 = bytes[(y0 * frameWidth + x0) * 4 + channel]
  const p10 = bytes[(y0 * frameWidth + x1) * 4 + channel]
  const p01 = bytes[(y1 * frameWidth + x0) * 4 + channel]
  const p11 = bytes[(y1 * frameWidth + x1) * 4 + channel]
  const top = p00 + (p10 - p00) * dx
  const bottom = p01 + (p11 - p01) * dx
  return top + (bottom - top) * dy
}

function preprocessCameraFrame(frame, guideRect) {
  if (!frame || !Number.isInteger(frame.width) || !Number.isInteger(frame.height)) {
    throw new Error('相机帧缺少有效 width/height')
  }
  if (frame.width <= 0 || frame.height <= 0) {
    throw new Error('相机帧尺寸必须大于 0')
  }
  const bytes = asUint8Array(frame.data)
  const expectedBytes = frame.width * frame.height * 4
  if (bytes.byteLength < expectedBytes) {
    throw new Error(`相机帧不是预期的 RGBA 数据: ${bytes.byteLength}/${expectedBytes}`)
  }

  const rect = normalizeGuideRect(guideRect)
  const cropX = rect.x * frame.width
  const cropY = rect.y * frame.height
  const cropWidth = rect.width * frame.width
  const cropHeight = rect.height * frame.height
  const output = new Float32Array(CHANNEL_SIZE * 3)

  for (let outY = 0; outY < MODEL_SIZE; outY += 1) {
    const srcY = cropY + ((outY + 0.5) * cropHeight) / MODEL_SIZE - 0.5
    for (let outX = 0; outX < MODEL_SIZE; outX += 1) {
      const srcX = cropX + ((outX + 0.5) * cropWidth) / MODEL_SIZE - 0.5
      const pixelIndex = outY * MODEL_SIZE + outX
      // CameraFrame is RGBA; the upstream FSA-Net demo intentionally uses BGR.
      const red = sampleRgbaBilinear(bytes, frame.width, frame.height, srcX, srcY, 0)
      const green = sampleRgbaBilinear(bytes, frame.width, frame.height, srcX, srcY, 1)
      const blue = sampleRgbaBilinear(bytes, frame.width, frame.height, srcX, srcY, 2)
      output[pixelIndex] = (blue - 127.5) / 128.0
      output[CHANNEL_SIZE + pixelIndex] = (green - 127.5) / 128.0
      output[CHANNEL_SIZE * 2 + pixelIndex] = (red - 127.5) / 128.0
    }
  }
  return output
}

function tensorValues(tensor) {
  if (!tensor || tensor.data == null) {
    throw new Error("推理结果缺少名为 'output' 的 Tensor")
  }
  if (tensor.data instanceof ArrayBuffer) {
    return new Float32Array(tensor.data)
  }
  if (ArrayBuffer.isView(tensor.data)) {
    return new Float32Array(
      tensor.data.buffer,
      tensor.data.byteOffset,
      Math.floor(tensor.data.byteLength / Float32Array.BYTES_PER_ELEMENT)
    )
  }
  throw new Error('输出 Tensor data 类型不受支持')
}

class HeadPoseInference {
  constructor(options) {
    const config = options || {}
    this.modelPath = config.modelPath || '/models/head_pose_fsanet_1x1.onnx'
    this.precisionLevel = config.precisionLevel == null ? 4 : config.precisionLevel
    this.allowNPU = config.allowNPU === true
    this.guideRect = normalizeGuideRect(config.guideRect)
    this.yawSign = assertYawSign(config.yawSign == null ? 1 : config.yawSign)
    this.onError = typeof config.onError === 'function' ? config.onError : null
    this.session = null
    this.loaded = false
    this.busy = false
    this.lastError = null
    this._loadPromise = null
  }

  load() {
    if (this.loaded) return Promise.resolve()
    if (this._loadPromise) return this._loadPromise
    if (typeof wx === 'undefined' || typeof wx.createInferenceSession !== 'function') {
      return Promise.reject(new Error('当前微信基础库不支持 wx.createInferenceSession'))
    }

    this._loadPromise = new Promise((resolve, reject) => {
      let settled = false
      try {
        this.session = wx.createInferenceSession({
          model: this.modelPath,
          precisionLevel: this.precisionLevel,
          allowNPU: this.allowNPU,
          allowQuantize: false,
          typicalShape: { input: [1, 3, MODEL_SIZE, MODEL_SIZE] },
        })
        this.session.onError((error) => {
          const message = error && error.errMsg ? error.errMsg : JSON.stringify(error)
          this.lastError = new Error(`头部姿态模型加载/推理失败: ${message}`)
          this.loaded = false
          if (this.onError) this.onError(this.lastError)
          if (!settled) {
            settled = true
            reject(this.lastError)
          }
        })
        this.session.onLoad(() => {
          if (settled) return
          settled = true
          this.loaded = true
          this.lastError = null
          resolve()
        })
      } catch (error) {
        settled = true
        reject(error)
      }
    })
    return this._loadPromise
  }

  setYawSign(value) {
    this.yawSign = assertYawSign(value)
  }

  canRun() {
    return this.loaded && !this.busy && !this.lastError
  }

  async estimateFrame(frame) {
    if (!this.loaded || !this.session) {
      throw new Error('头部姿态模型尚未加载完成')
    }
    if (this.lastError) throw this.lastError
    if (this.busy) throw new Error('上一帧推理尚未完成')

    this.busy = true
    try {
      const input = preprocessCameraFrame(frame, this.guideRect)
      const result = await this.session.run({
        input: {
          type: 'float32',
          data: input.buffer,
          shape: [1, 3, MODEL_SIZE, MODEL_SIZE],
        },
      })
      const values = tensorValues(result.output)
      if (values.length !== 3) {
        throw new Error(`模型 output 长度应为 3，实际为 ${values.length}`)
      }
      const yaw = values[0] * this.yawSign
      const pitch = values[1]
      const roll = values[2]
      const valid = [yaw, pitch, roll].every(
        (value) => Number.isFinite(value) && Math.abs(value) <= 99
      )
      return { yaw, pitch, roll, valid, timestamp: Date.now() }
    } finally {
      this.busy = false
    }
  }

  destroy() {
    if (this.session && typeof this.session.destroy === 'function') {
      this.session.destroy()
    }
    this.session = null
    this.loaded = false
    this.busy = false
    this._loadPromise = null
  }
}

module.exports = {
  DEFAULT_GUIDE_RECT,
  HeadPoseInference,
  preprocessCameraFrame,
}

'use strict'

const DEFAULT_TARGETS = Object.freeze([
  Object.freeze({ id: 'left', label: '左侧', yaw: -60 }),
  Object.freeze({ id: 'front', label: '正面', yaw: 0 }),
  Object.freeze({ id: 'right', label: '右侧', yaw: 60 }),
])

const DEFAULT_CONFIG = Object.freeze({
  yawToleranceDeg: 8,
  maxAbsPitchDeg: 12,
  maxAbsRollDeg: 12,
  stableMs: 400,
  cooldownMs: 1000,
  smoothingWindow: 5,
})

function finiteNumber(value, name) {
  if (!Number.isFinite(value)) throw new Error(`${name} 必须是有限数字`)
  return value
}

function normalizeTargets(targets) {
  if (!Array.isArray(targets) || targets.length === 0) {
    throw new Error('targets 至少需要一个目标角度')
  }
  const ids = new Set()
  return targets.map((target, index) => {
    const id = String(target.id == null ? index : target.id)
    if (ids.has(id)) throw new Error(`target id 重复: ${id}`)
    ids.add(id)
    const yaw = finiteNumber(Number(target.yaw), `targets[${index}].yaw`)
    if (Math.abs(yaw) > 90) throw new Error('目标 yaw 必须位于 [-90, 90]')
    return { id, label: String(target.label || id), yaw }
  })
}

function normalizeConfig(config) {
  const merged = Object.assign({}, DEFAULT_CONFIG, config || {})
  ;['yawToleranceDeg', 'maxAbsPitchDeg', 'maxAbsRollDeg', 'stableMs', 'cooldownMs'].forEach(
    (key) => {
      merged[key] = finiteNumber(Number(merged[key]), key)
    }
  )
  if (merged.yawToleranceDeg <= 0 || merged.yawToleranceDeg > 45) {
    throw new Error('yawToleranceDeg 必须位于 (0, 45]')
  }
  if (merged.maxAbsPitchDeg <= 0 || merged.maxAbsRollDeg <= 0) {
    throw new Error('pitch/roll 限制必须大于 0')
  }
  if (merged.stableMs < 0 || merged.cooldownMs < 0) {
    throw new Error('stableMs/cooldownMs 不能为负数')
  }
  merged.smoothingWindow = Math.max(
    1,
    Math.round(finiteNumber(Number(merged.smoothingWindow), 'smoothingWindow'))
  )
  return merged
}

function median(values) {
  const sorted = values.slice().sort((a, b) => a - b)
  const middle = Math.floor(sorted.length / 2)
  if (sorted.length % 2) return sorted[middle]
  return (sorted[middle - 1] + sorted[middle]) / 2
}

class CaptureGate {
  constructor(options) {
    const config = options || {}
    this.targets = normalizeTargets(config.targets || DEFAULT_TARGETS)
    this.config = normalizeConfig(config)
    this.reset()
  }

  reset() {
    this.targetIndex = 0
    this.state = 'searching'
    this.holdStartedAt = null
    this.cooldownUntil = 0
    this.history = []
  }

  setTargets(targets) {
    this.targets = normalizeTargets(targets)
    this.reset()
  }

  currentTarget() {
    return this.targetIndex < this.targets.length ? this.targets[this.targetIndex] : null
  }

  _pushPose(pose) {
    this.history.push({ yaw: pose.yaw, pitch: pose.pitch, roll: pose.roll })
    if (this.history.length > this.config.smoothingWindow) this.history.shift()
    return {
      yaw: median(this.history.map((item) => item.yaw)),
      pitch: median(this.history.map((item) => item.pitch)),
      roll: median(this.history.map((item) => item.roll)),
    }
  }

  _resetHold(state) {
    this.state = state || 'searching'
    this.holdStartedAt = null
  }

  update(pose) {
    const target = this.currentTarget()
    const now = pose && Number.isFinite(pose.timestamp) ? pose.timestamp : Date.now()
    if (!target) return this.snapshot(null, 1, false)
    if (this.state === 'capturing') return this.snapshot(null, 1, false)
    if (now < this.cooldownUntil) return this.snapshot(null, 0, false)
    if (
      !pose ||
      pose.valid !== true ||
      ![pose.yaw, pose.pitch, pose.roll].every(Number.isFinite)
    ) {
      this.history = []
      this._resetHold('invalid')
      return this.snapshot(null, 0, false)
    }

    const smoothed = this._pushPose(pose)
    const within =
      Math.abs(smoothed.yaw - target.yaw) <= this.config.yawToleranceDeg &&
      Math.abs(smoothed.pitch) <= this.config.maxAbsPitchDeg &&
      Math.abs(smoothed.roll) <= this.config.maxAbsRollDeg
    if (!within) {
      this._resetHold('searching')
      return this.snapshot(smoothed, 0, false)
    }

    if (this.holdStartedAt == null) {
      this.holdStartedAt = now
      this.state = 'holding'
    }
    const heldMs = Math.max(0, now - this.holdStartedAt)
    const progress = this.config.stableMs === 0 ? 1 : Math.min(1, heldMs / this.config.stableMs)
    if (progress >= 1) {
      this.state = 'capturing'
      return this.snapshot(smoothed, 1, true)
    }
    return this.snapshot(smoothed, progress, false)
  }

  markCaptured(timestamp) {
    if (this.state !== 'capturing') return this.snapshot(null, 0, false)
    this.targetIndex += 1
    this.history = []
    this.holdStartedAt = null
    if (!this.currentTarget()) {
      this.state = 'complete'
      return this.snapshot(null, 1, false)
    }
    this.state = 'cooldown'
    this.cooldownUntil = (Number.isFinite(timestamp) ? timestamp : Date.now()) + this.config.cooldownMs
    return this.snapshot(null, 0, false)
  }

  markCaptureFailed() {
    this.history = []
    this._resetHold('searching')
    return this.snapshot(null, 0, false)
  }

  snapshot(smoothedPose, progress, shouldCapture) {
    return {
      state: this.currentTarget() ? this.state : 'complete',
      target: this.currentTarget(),
      targetIndex: this.targetIndex,
      targetCount: this.targets.length,
      progress: Number(progress || 0),
      shouldCapture: shouldCapture === true,
      pose: smoothedPose,
    }
  }
}

function createThreeViewTargets(sideAngleDeg) {
  const angle = finiteNumber(Number(sideAngleDeg), 'sideAngleDeg')
  if (angle <= 0 || angle > 90) throw new Error('sideAngleDeg 必须位于 (0, 90]')
  return [
    { id: 'left', label: '左侧', yaw: -angle },
    { id: 'front', label: '正面', yaw: 0 },
    { id: 'right', label: '右侧', yaw: angle },
  ]
}

module.exports = {
  CaptureGate,
  DEFAULT_CONFIG,
  DEFAULT_TARGETS,
  createThreeViewTargets,
}

