      <view class="target">{{targetLabel}} {{targetYaw}}°</view>
    </view>
    <view class="camera-status">
      <text>{{currentIndex}} / {{targetCount}}</text>
      <text>{{modelStatus}}</text>
    </view>
  </view>

  <view class="panel">
    <view class="pose-row" wx:if="{{pose}}">
      <text>Yaw {{pose.yaw}}°</text>
      <text>Pitch {{pose.pitch}}°</text>
      <text>Roll {{pose.roll}}°</text>
    </view>
    <view class="pose-row muted" wx:else>等待第一帧真机推理结果</view>

    <view class="progress-track">
      <view class="progress-fill" style="width: {{progressPercent}}%;" />
    </view>
    <view class="hint">
      <text wx:if="{{gateState === 'holding'}}">保持不动，稳定后自动拍照</text>
      <text wx:elif="{{gateState === 'capturing'}}">正在拍照…</text>
      <text wx:elif="{{completed}}">三视图已经拍摄完成</text>
      <text wx:else>把脸放入椭圆，并转到目标角度</text>
    </view>

    <view class="settings">
      <label>侧脸角度</label>
      <input type="digit" value="{{sideAngleDeg}}" bindinput="onSideAngleInput" />
      <label>允许误差</label>
      <input type="digit" value="{{toleranceDeg}}" bindinput="onToleranceInput" />
      <button size="mini" bindtap="applySettings">应用</button>
    </view>

    <view class="actions">
      <button bindtap="toggleYawSign">切换左右方向（{{yawSign}}）</button>
      <button bindtap="resetSequence">重新拍摄</button>
    </view>

    <view class="error" wx:if="{{error}}">{{error}}</view>
    <view class="device-note">AI 推理接口需要微信真机验证；加载失败时不会使用模拟角度拍照。</view>

    <scroll-view class="photos" scroll-x wx:if="{{photos.length}}">
      <view class="photo" wx:for="{{photos}}" wx:key="id">
        <image src="{{item.path}}" mode="aspectFill" />
        <text>{{item.label}} {{item.yaw}}°</text>
      </view>
    </scroll-view>
  </view>
</view>

