  assert.ok(Math.abs(tensor[64 * 64] - (20 - 127.5) / 128) < 1e-6)
  assert.ok(Math.abs(tensor[2 * 64 * 64] - (30 - 127.5) / 128) < 1e-6)
}

function testInvalidFrameRejected() {
