'use strict'

const assert = require('assert')
const {
  CaptureGate,
  createThreeViewTargets,
} = require('../miniprogram_demo/utils/captureGate.js')

function pose(yaw, timestamp, pitch = 0, roll = 0) {
  return { yaw, pitch, roll, valid: true, timestamp }
}

function testStableCaptureAndAdvance() {
  const gate = new CaptureGate({
    targets: createThreeViewTargets(60),
    yawToleranceDeg: 8,
    stableMs: 400,
    cooldownMs: 1000,
    smoothingWindow: 3,
  })
  assert.strictEqual(gate.update(pose(-60, 0)).state, 'holding')
  assert.strictEqual(gate.update(pose(-59, 200)).shouldCapture, false)
  const ready = gate.update(pose(-61, 400))
  assert.strictEqual(ready.shouldCapture, true)
  assert.strictEqual(ready.target.id, 'left')

  const advanced = gate.markCaptured(400)
  assert.strictEqual(advanced.target.id, 'front')
  assert.strictEqual(advanced.state, 'cooldown')
  assert.strictEqual(gate.update(pose(0, 1000)).state, 'cooldown')
  assert.strictEqual(gate.update(pose(0, 1400)).state, 'holding')
  assert.strictEqual(gate.update(pose(0, 1800)).shouldCapture, true)
}

function testInvalidPoseNeverCaptures() {
  const gate = new CaptureGate({ stableMs: 0, smoothingWindow: 1 })
  const invalid = gate.update({ yaw: -60, pitch: 0, roll: 0, valid: false, timestamp: 0 })
  assert.strictEqual(invalid.shouldCapture, false)
  assert.strictEqual(invalid.state, 'invalid')
  const badPitch = gate.update(pose(-60, 100, 30, 0))
  assert.strictEqual(badPitch.shouldCapture, false)
}

function testConfigurableAngles() {
  const targets = createThreeViewTargets(45)
  assert.deepStrictEqual(
    targets.map((target) => target.yaw),
    [-45, 0, 45]
  )
  assert.throws(() => createThreeViewTargets(0))
  assert.throws(() => createThreeViewTargets(91))
}

testStableCaptureAndAdvance()
testInvalidPoseNeverCaptures()
testConfigurableAngles()
console.log('captureGate tests passed')

